INSERT INTO "public"."types" ("id", "nom", "id_famille", "description", "constructeur_id") VALUES (1, 'Corail réversible', 5, 'Matériel voyageurs réversible de la SNCF, mis en service pour les relations Intercités et TER.', null), (2, 'BB 26000', 4, 'Locomotives électriques de ligne multicourant de la SNCF, mises en service à partir de 1988, destinées aux trains voyageurs et fret.', null), (3, 'BB 37000', 4, 'Locomotives électriques bicourant de fret de la SNCF, mises en service à partir de 2002, destinées aux trafics transfrontaliers.', null), (4, 'E 37500', 4, 'Locomotives diesel-électriques de fret de la SNCF, mises en service à partir de 2003, utilisées sur les lignes non électrifiées.', null), (5, 'BB 75000', 4, 'Locomotives diesel-électriques de fret de la SNCF, mises en service à partir de 2006, destinées aux trains lourds.', null), (6, 'BB 60000', 4, 'Locomotives diesel de manœuvre et de desserte locale de la SNCF, mises en service à partir de 2004.', null), (7, 'F140 AC1', 9, 'Locomotive électrique de ligne, utilisée pour le fret et les trains voyageurs longue distance.', null), (8, 'BB 27000', 4, 'Locomotives électriques de fret de la SNCF, mises en service à partir de 2001, principalement utilisées sur les grands axes électrifiés.', null), (9, 'ESV', 3, 'Locomotive ou engin électrique de service pour le réseau SNCF, utilisée pour les opérations d’entretien et de maintenance.', null), (10, 'Y 8000', 6, 'Locotracteurs diesel de manœuvre de la SNCF, mis en service à partir des années 1980.', null), (11, 'BB 22200', 4, 'Locomotives électriques de ligne bicourant de la SNCF, mises en service à partir de 1976, et toujours en service.', null), (12, 'Z 31500', 7, 'Matériel électrique du Régiolis, train de la SNCF, destiné aux relations du réseau transfrontalier Léman Express.', null), (13, 'Z 51500', 7, 'Matériel électrique du Régiolis, train de la SNCF.', null), (14, 'Z 54500', 7, 'Matériel électrique du Régiolis, train de la SNCF.', null), (15, 'Z 54900', 7, 'M